[
  {
    "alert_id": "AKI_TDF_ATTRUTION",
    "title": "Acute kidney injury: TDF vs dehydration",
    "message": "Guidelines list acute kidney injury as a TDF toxicity and recommend substituting TDF with ABC if GFR <60 mL/min. Patient has severe AKI (creatinine 2.4, up from 0.9). Evidence FOR drug attribution: TDF is nephrotoxic and patient has been on it 2 years. Evidence AGAINST: presentation is classic prerenal AKI from gastroenteritis—urea:creatinine ratio 24:1, hypotension, tachycardia, hypokalaemia, hyponatraemia, and urinalysis shows no protein or glucose (TDF toxicity typically causes proteinuria/glycosuria). Two family members share the illness, supporting infectious gastroenteritis. TDF may be contributing but dehydration is the primary driver.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Resuscitate first; reassess creatinine after hydration. If renal function recovers, TDF may be continued. If GFR remains <60, substitute TDF with ABC per guidelines.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 6, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p6_c1"}
    ]
  },
  {
    "alert_id": "PERMANENT_TDF_STOP_PREMATURE",
    "title": "Permanent TDF discontinuation may be premature",
    "message": "Guidelines state that for severe reactions, the responsible medicine should be substituted, and ART resumed with substitution when the patient is stable. The clinician is considering stopping TDF permanently. However, this AKI has a strong prerenal component (urea:creatinine ratio 24:1, dehydration, no proteinuria) and may fully reverse with IV fluids. Permanent discontinuation before reassessment after resuscitation risks unnecessary loss of an effective first-line regimen. Guidelines recommend substitution with ABC when GFR <60, not necessarily permanent discontinuation.",
    "issue_type": "plan_review",
    "severity": "moderate",
    "recommended_action": "Defer the permanent discontinipation decision until renal function is reassessed post-resuscitation. If GFR remains <60, substitute TDF with ABC+3TC+DTG.",
    "citations": [
      {"page_number": 34, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p34_c2"},
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 6, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p6_c1"}
    ]
  },
  {
    "alert_id": "TDF_RENAL_MONITORING_GAP",
    "title": "TDF renal monitoring overdue by 1 month",
    "message": "Guidelines require serum creatinine and eGFR every 12 months for patients on TDF. Patient's last creatinine was 2025-02-14, which is 375 days (over 12 months) before the current visit. No routine TDF renal monitoring was performed between that date and today's acute presentation. This gap means chronic TDF nephrotoxicity, if developing, could have been missed earlier.",
    "issue_type": "monitoring_gap",
    "severity": "low",
    "recommended_action": "After acute management, ensure annual serum creatinine and eGFR monitoring is scheduled and documented for ongoing TDF therapy.",
    "citations": [
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  }
]
